import { mkdir, readFile, writeFile } from "node:fs/promises";
import { buildSystemPrompt } from "../src/catalog-source.js";

const target = new URL("../src/generated/prompt.ts", import.meta.url);

const prompt = buildSystemPrompt();

const content = [
  "// Generated by npm run generate:prompt. Do not edit; see src/catalog-source.ts.",
  `export const systemPrompt = ${JSON.stringify(prompt)};`,
  "",
  "export const modelPrompt = systemPrompt;",
  "",
].join("\n");

if (process.argv.includes("--check")) {
  const current = await readFile(target, "utf8").catch(error => {
    if (error.code === "ENOENT") return undefined;
    throw error;
  });

  if (current !== content) {
    console.error("Generated OpenUI prompt is missing or stale. Run npm run generate:prompt.");
    process.exitCode = 1;
  } else {
    console.log("Generated OpenUI prompt is current.");
  }
} else {
  await mkdir(new URL("../src/generated/", import.meta.url), { recursive: true });
  await writeFile(target, content);
  console.log("Generated src/generated/prompt.ts.");
}
